"""JSON log lines on stdout: {"t": seconds since start, "event": ..., ...}. The run's logs are what we debug from.

Secrets never reach the log: the run token (also inside LLM_PROXY_URL and every *_BASE_URL) and the website
passwords are masked wherever they appear.
"""
from __future__ import annotations

import json
import os
import sys
import time

START = time.monotonic()
_secrets: set[str] = set()


def add_secret(value: str | None) -> None:
    if value and len(value) >= 6:
        _secrets.add(value)


def add_secrets_from_env(env=os.environ) -> None:
    add_secret(env.get("CHALLENGE_RUN_TOKEN"))
    for key, value in env.items():
        if key.endswith("_API_KEY") and value != "local":
            add_secret(value)


def redact(text: str) -> str:
    for s in _secrets:
        text = text.replace(s, "[secret]")
    return text


def elapsed() -> float:
    return round(time.monotonic() - START, 2)


def log(event: str | dict, **fields) -> None:
    """log("phase", name="P1") or log({"event": "browser", ...}) — the dict form is what the tools pass."""
    record = dict(event) if isinstance(event, dict) else {"event": event}
    record.update(fields)
    line = json.dumps({"t": elapsed(), **record}, ensure_ascii=False, default=str)
    print(redact(line), file=sys.stdout, flush=True)

"""The run contract: read the run (brief, websites and logins, where the answer goes) and keep the clock.

In a test or scored run the platform sets CHALLENGE_API_URL and CHALLENGE_RUN_TOKEN. On our machines there is no
run token: `eval "$(atira scout --env)"` exports the public scouting run as CHALLENGE_SCOUTING instead (nothing done
with those logins counts), and the clock gets the same 20 minutes a scored run has, so local runs behave alike.
Docs: $API/docs/run-contract.md
"""
from __future__ import annotations

import json
import os
import time
from dataclasses import dataclass, field
from urllib.error import HTTPError, URLError
from urllib.request import Request, urlopen

from . import log as logging

USER_AGENT = "isar-labs-rfq-agent/0.1"  # the API's edge refuses Python's default urllib agent
LOCAL_RUN_S = 20 * 60
LOAD_SCOUTING = 'eval "$(atira scout --env)"'


@dataclass
class Run:
    brief: str
    access: list[dict]                # per website: siteId, url, credentials {username, password}
    submission: dict                  # {"kind": "site", "siteId", "url"} or {"kind": "api", "url"}
    answer_schema: dict
    expires_at: float                 # epoch seconds
    token: str | None = None          # None locally
    run_id: str | None = None
    answer_url: str | None = None
    raw: dict = field(default_factory=dict, repr=False)

    @property
    def local(self) -> bool:
        return self.token is None

    def seconds_left(self, now: float | None = None) -> float:
        """Until the answer is refused and the run scores 0."""
        return self.expires_at - (time.time() if now is None else now)


def http(url: str, token: str | None = None, payload: dict | None = None, timeout: float = 30) -> tuple[int, str]:
    """GET (or POST `payload` as JSON) with the run token in x-api-key: the status and the body."""
    headers = {"Accept": "application/json", "User-Agent": USER_AGENT}
    if token:
        headers["x-api-key"] = token
    data = None
    if payload is not None:
        data = json.dumps(payload, ensure_ascii=False).encode()
        headers["Content-Type"] = "application/json"
    try:
        with urlopen(Request(url, data=data, headers=headers), timeout=timeout) as response:
            return response.status, response.read().decode("utf-8", errors="replace")
    except HTTPError as error:
        return error.code, error.read().decode("utf-8", errors="replace")


def _from_json(d: dict, token: str | None, now: float) -> Run:
    expires = d.get("expires_at")
    expires_at = expires / 1000 if isinstance(expires, (int, float)) else now + LOCAL_RUN_S
    return Run(brief=d.get("brief") or "", access=d.get("access") or [], submission=d.get("submission") or {},
               answer_schema=d.get("answer_schema") or {}, expires_at=expires_at, token=token,
               run_id=d.get("run_id"), answer_url=d.get("answer_url"), raw=d)


def load_run(env=os.environ, now: float | None = None, sleep=time.sleep) -> Run:
    """The run; locally, without a token, the scouting run that `atira scout --env` exported."""
    now = time.time() if now is None else now
    token = env.get("CHALLENGE_RUN_TOKEN")
    logging.add_secrets_from_env(env)
    if not token:
        if not env.get("CHALLENGE_SCOUTING"):
            raise SystemExit(f"No run token and no scouting logins. To develop locally: {LOAD_SCOUTING}")
        try:
            run = _from_json(json.loads(env["CHALLENGE_SCOUTING"]), None, now)
        except ValueError:
            raise SystemExit(f"CHALLENGE_SCOUTING is not the JSON atira exports. Load it again: {LOAD_SCOUTING}")
    else:
        url = env["CHALLENGE_API_URL"].rstrip("/") + "/v1/runs/current"
        status, body = 0, ""
        for attempt in range(5):  # rides out a restart of the API
            try:
                status, body = http(url, token)
            except (URLError, OSError) as error:
                status, body = 0, str(error)
            if status == 200:
                break
            if status in (401, 403, 404):  # the run is over, or the token is wrong: no point in asking again
                raise SystemExit(f"Cannot read the run: HTTP {status} {logging.redact(body[:300])}")
            sleep(2 * (attempt + 1))
        else:
            raise SystemExit(f"Cannot read the run: HTTP {status} {logging.redact(body[:300])}")
        run = _from_json(json.loads(body), token, now)
    for site in run.access:
        logging.add_secret((site.get("credentials") or {}).get("password"))
    return run


def submit_answer(run: Run, answer: dict) -> tuple[int, str]:
    """POST the answer to an "api" submission target. 202: accepted and final. 400: the body lists the issues;
    nothing is recorded, fix the answer and send it again. A "site" submission is entered on the website instead."""
    if run.submission.get("kind") != "api":
        raise ValueError("This run takes its answer on a website, not through the API")
    if run.local:
        raise ValueError("No run to answer locally: test it in a run (atira test-run ./agent)")
    return http(run.answer_url or run.submission["url"], run.token, answer, timeout=60)

"""The hosted Qwen (Qwen3.8-Flash-Next, OpenAI-compatible): one place for every model call.

- thinking off for navigation (≈ as fast as on for short calls, far fewer tokens), on for reading and deciding
- retries with backoff on timeouts, 429 and 5xx; an empty reply counts as a failure
- a concurrency limit per run: the hosted model allows 32 calls at once for the whole team, test runs included
- tool calls that arrive as text in the content are recovered
- every call is logged with tokens and its cost at the simulated prices, and summed per agent

Every run gets QWEN_BASE_URL and QWEN_API_KEY; locally `atira scout --env` points them at `atira models proxy`.
"""
from __future__ import annotations

import asyncio
import json
import os
import re
import time
from dataclasses import dataclass, field

import httpx
from openai import (APIConnectionError, APIStatusError, APITimeoutError, AsyncOpenAI, InternalServerError,
                    RateLimitError)

from .. import log as logging

MODEL = "qwen3.8-flash-next"
PRICE_PER_M = {"input": 0.15, "cached": 0.016, "output": 0.47}  # USD, the platform's simulated prices
TIMEOUT_S = 360          # an idle model takes minutes to wake on its first call
RETRIES = 5
CONCURRENCY = 8


@dataclass
class ToolCall:
    id: str
    name: str
    args: dict | None          # None when the arguments were not valid JSON (see `error`)
    error: str | None = None


@dataclass
class Usage:
    calls: int = 0
    input: int = 0
    cached: int = 0
    output: int = 0
    seconds: float = 0.0

    @property
    def cost(self) -> float:
        p = PRICE_PER_M
        return ((self.input - self.cached) * p["input"] + self.cached * p["cached"] + self.output * p["output"]) / 1e6

    def add(self, other: "Usage") -> None:
        for k in ("calls", "input", "cached", "output", "seconds"):
            setattr(self, k, getattr(self, k) + getattr(other, k))


@dataclass
class Reply:
    text: str
    tool_calls: list[ToolCall] = field(default_factory=list)
    finish_reason: str | None = None
    usage: Usage = field(default_factory=Usage)
    message: dict = field(default_factory=dict)   # the assistant message to append to the conversation

    def json(self) -> dict | list:
        """The reply as JSON (JSON mode or a ```json block); raises ValueError otherwise."""
        return parse_json(self.text)


def parse_json(text: str):
    text = (text or "").strip()
    m = re.search(r"```(?:json)?\s*(.*?)```", text, re.S)
    if m:
        text = m.group(1).strip()
    try:
        return json.loads(text)
    except ValueError:
        start = min((i for i in (text.find("{"), text.find("[")) if i >= 0), default=-1)
        if start < 0:
            raise
        return json.loads(text[start:text.rfind("}" if text[start] == "{" else "]") + 1])


_TEXT_CALL = re.compile(r"<tool_call>\s*(\{.*?\})\s*</tool_call>|(\{\s*\"name\"\s*:.*\})", re.S)


def _text_tool_calls(text: str, tool_names: set[str]) -> list[ToolCall]:
    """Tool calls the model wrote into the content instead of `tool_calls`."""
    calls = []
    for i, m in enumerate(_TEXT_CALL.finditer(text or "")):
        try:
            d = json.loads(m.group(1) or m.group(2))
        except ValueError:
            continue
        name = d.get("name") or (d.get("function") or {}).get("name")
        args = d.get("arguments", d.get("parameters", {}))
        if name in tool_names:
            calls.append(ToolCall(id=f"text_{i}", name=name, args=json.loads(args) if isinstance(args, str) else args))
    return calls


class LLM:
    def __init__(self, base_url: str | None = None, api_key: str | None = None, model: str | None = None,
                 concurrency: int | None = None, http_client: httpx.AsyncClient | None = None, env=os.environ,
                 sleep=asyncio.sleep):
        self.model = model or env.get("RFQ_QWEN_MODEL") or MODEL
        self.client = AsyncOpenAI(base_url=base_url or env["QWEN_BASE_URL"], api_key=api_key or env["QWEN_API_KEY"],
                                  timeout=TIMEOUT_S, max_retries=0, http_client=http_client)
        self.limit = asyncio.Semaphore(concurrency or int(env.get("RFQ_LLM_CONCURRENCY") or CONCURRENCY))
        self.usage: dict[str, Usage] = {}
        self._sleep = sleep

    async def chat(self, messages: list[dict], *, tools: list[dict] | None = None, thinking: bool = False,
                   json_mode: bool = False, temperature: float = 0.0, max_tokens: int | None = None,
                   agent: str = "main") -> Reply:
        kwargs = {"model": self.model, "messages": messages, "temperature": temperature,
                  "extra_body": {"chat_template_kwargs": {"enable_thinking": thinking}}}
        if tools:
            kwargs["tools"] = tools
        if json_mode:
            kwargs["response_format"] = {"type": "json_object"}
        if max_tokens:
            kwargs["max_tokens"] = max_tokens
        last: Exception | None = None
        for attempt in range(RETRIES):
            if attempt:
                await self._sleep(min(0.5 * 2 ** (attempt - 1), 8))
            start = time.monotonic()
            try:
                async with self.limit:
                    resp = await self.client.chat.completions.create(**kwargs)
            except (APITimeoutError, APIConnectionError, RateLimitError, InternalServerError) as e:
                last = e
                logging.log("llm_retry", agent=agent, attempt=attempt + 1, error=f"{type(e).__name__}: {str(e)[:160]}")
                continue
            except APIStatusError as e:  # 4xx other than 429: the request itself is wrong, retrying won't help
                logging.log("llm_error", agent=agent, status=e.status_code, error=str(e)[:300])
                raise
            reply = self._reply(resp, tools, time.monotonic() - start, agent, thinking)
            if reply.text.strip() or reply.tool_calls:
                return reply
            last = RuntimeError(f"empty reply (finish_reason={reply.finish_reason})")
            logging.log("llm_retry", agent=agent, attempt=attempt + 1, error=str(last))
        raise RuntimeError(f"model call failed after {RETRIES} attempts: {last}")

    def _reply(self, resp, tools, seconds: float, agent: str, thinking: bool) -> Reply:
        choice = resp.choices[0]
        msg = choice.message
        u = resp.usage
        cached = ((u.prompt_tokens_details.cached_tokens if u and u.prompt_tokens_details else 0) or 0)
        usage = Usage(calls=1, input=u.prompt_tokens if u else 0, cached=cached,
                      output=u.completion_tokens if u else 0, seconds=seconds)
        self.usage.setdefault(agent, Usage()).add(usage)
        calls = []
        for tc in msg.tool_calls or []:
            try:
                args = json.loads(tc.function.arguments or "{}")
                calls.append(ToolCall(id=tc.id, name=tc.function.name, args=args if isinstance(args, dict) else {}))
            except ValueError as e:
                calls.append(ToolCall(id=tc.id, name=tc.function.name, args=None, error=f"arguments are not JSON: {e}"))
        text = msg.content or ""
        if tools and not calls:
            calls = _text_tool_calls(text, {t["function"]["name"] for t in tools})
        message = {"role": "assistant", "content": text}
        if calls:
            message["tool_calls"] = [{"id": c.id, "type": "function", "function": {
                "name": c.name, "arguments": json.dumps(c.args if c.args is not None else {}, ensure_ascii=False)}}
                for c in calls]
        logging.log("llm", agent=agent, s=round(seconds, 2), thinking=thinking, input=usage.input, cached=usage.cached,
                    output=usage.output, cost=round(usage.cost, 6), finish=choice.finish_reason,
                    tools=[c.name for c in calls] or None)
        return Reply(text=text, tool_calls=calls, finish_reason=choice.finish_reason, usage=usage, message=message)

    def total(self) -> Usage:
        t = Usage()
        for u in self.usage.values():
            t.add(u)
        return t

    def summary(self) -> dict:
        """Calls, tokens, seconds in calls and cost per agent, plus the total — logged at the end of a run."""
        rows = {a: {"calls": u.calls, "input": u.input, "cached": u.cached, "output": u.output,
                    "s": round(u.seconds, 1), "cost": round(u.cost, 5)} for a, u in self.usage.items()}
        t = self.total()
        rows["total"] = {"calls": t.calls, "input": t.input, "cached": t.cached, "output": t.output,
                         "s": round(t.seconds, 1), "cost": round(t.cost, 5)}
        return rows

"""Qwen client against a fake OpenAI endpoint. Values are made up."""
import asyncio
import json
import sys
from pathlib import Path

import httpx
import openai
import pytest

sys.path.insert(0, str(Path(__file__).parents[1]))
from rfq.llm import LLM, parse_json  # noqa: E402

TOOLS = [{"type": "function", "function": {"name": "click", "description": "Click",
                                            "parameters": {"type": "object", "properties": {"ref": {"type": "string"}}}}}]


def completion(content="", tool_calls=None, prompt=100, cached=0, out=10, finish="stop"):
    msg = {"role": "assistant", "content": content}
    if tool_calls:
        msg["tool_calls"] = tool_calls
    return {"id": "c1", "object": "chat.completion", "created": 0, "model": "qwen",
            "choices": [{"index": 0, "message": msg, "finish_reason": finish}],
            "usage": {"prompt_tokens": prompt, "completion_tokens": out, "total_tokens": prompt + out,
                      "prompt_tokens_details": {"cached_tokens": cached}}}


def make(replies):
    """An LLM whose endpoint answers with `replies` in order (dicts → 200 JSON, ints → that status)."""
    seen = []

    def handler(request):
        seen.append(json.loads(request.content))
        r = replies.pop(0)
        return httpx.Response(r, json={"error": {"message": "x"}}) if isinstance(r, int) else httpx.Response(200, json=r)

    async def no_sleep(_):
        pass
    llm = LLM(base_url="http://qwen.test/v1", api_key="k", http_client=httpx.AsyncClient(transport=httpx.MockTransport(handler)),
              sleep=no_sleep)
    return llm, seen


def test_tool_call_thinking_flag_and_cost():
    tc = [{"id": "t1", "type": "function", "function": {"name": "click", "arguments": '{"ref": "e2"}'}}]
    llm, seen = make([completion(tool_calls=tc, prompt=1_000_000, cached=400_000, out=100_000, finish="tool_calls")])
    r = asyncio.run(llm.chat([{"role": "user", "content": "x"}], tools=TOOLS, agent="nav"))
    assert [(c.name, c.args) for c in r.tool_calls] == [("click", {"ref": "e2"})]
    assert seen[0]["extra_body"] if "extra_body" in seen[0] else seen[0]["chat_template_kwargs"] == {"enable_thinking": False}
    assert r.message["tool_calls"][0]["function"]["name"] == "click"
    # 600k uncached × 0.15 + 400k cached × 0.016 + 100k out × 0.47 per million
    assert llm.usage["nav"].cost == pytest.approx(0.09 + 0.0064 + 0.047)
    assert llm.summary()["total"]["calls"] == 1


def test_retries_5xx_429_and_empty_replies():
    llm, seen = make([503, 429, completion(content=""), completion(content="ok")])
    r = asyncio.run(llm.chat([{"role": "user", "content": "x"}]))
    assert r.text == "ok" and len(seen) == 4


def test_gives_up_after_retries():
    llm, _ = make([500] * 5)
    with pytest.raises(RuntimeError, match="after 5 attempts"):
        asyncio.run(llm.chat([{"role": "user", "content": "x"}]))


def test_client_errors_are_not_retried():
    llm, seen = make([400])
    with pytest.raises(openai.BadRequestError):
        asyncio.run(llm.chat([{"role": "user", "content": "x"}]))
    assert len(seen) == 1


def test_tool_call_written_as_text_is_recovered():
    llm, _ = make([completion(content='Ich klicke.\n<tool_call>{"name": "click", "arguments": {"ref": "e5"}}</tool_call>')])
    r = asyncio.run(llm.chat([{"role": "user", "content": "x"}], tools=TOOLS))
    assert [(c.name, c.args) for c in r.tool_calls] == [("click", {"ref": "e5"})]


def test_broken_tool_arguments_become_an_error_for_the_model():
    tc = [{"id": "t1", "type": "function", "function": {"name": "click", "arguments": '{"ref": e2'}}]
    llm, _ = make([completion(tool_calls=tc)])
    r = asyncio.run(llm.chat([{"role": "user", "content": "x"}], tools=TOOLS))
    assert r.tool_calls[0].args is None and "not JSON" in r.tool_calls[0].error


def test_json_mode_and_thinking_on_are_sent():
    llm, seen = make([completion(content='{"a": 1}')])
    r = asyncio.run(llm.chat([{"role": "user", "content": "x"}], json_mode=True, thinking=True))
    assert r.json() == {"a": 1}
    assert seen[0]["response_format"] == {"type": "json_object"}
    assert seen[0]["chat_template_kwargs"] == {"enable_thinking": True}


@pytest.mark.parametrize("text", ['{"a": 1}', '```json\n{"a": 1}\n```', 'Ergebnis: {"a": 1} fertig'])
def test_parse_json_variants(text):
    assert parse_json(text) == {"a": 1}

