async def _name(self, loc: Locator) -> str:
    """Role and visible name of an element, so a result says what was actually clicked."""
    try:
        return await loc.evaluate("""e => { const n = (e.getAttribute('aria-label') || e.innerText || e.value || '')
            .replace(/\\s+/g, ' ').trim().slice(0, 80); return (e.getAttribute('role') || e.tagName.toLowerCase()) + ' "' + n + '"'; }""")
    except Exception:
        return ""

async def click(self, ref: str) -> str:
    async def go():
        loc = await self._locate(ref)
        if await self._attr(loc, "disabled") is not None or await self._attr(loc, "aria-disabled") == "true":
            raise ToolError(f"{ref} ist deaktiviert — anderes Element wählen.")
        name = await self._name(loc)
        await self._click(loc)
        return f"Geklickt: {ref} ({name})" if name else f"Geklickt: {ref}"
    return await self._run(go, "")

