# Unlock gates: a slider and/or a "not a robot" checkbox that keep a form/area locked (disabled fieldset, inert).
# Only these two mechanics; anything to copy or decide (receipt numbers, options) stays with the model.
GATE_JS = r"""() => {
  const vis = (el) => el.offsetParent !== null || el.getClientRects().length > 0;
  const locked = document.querySelector("fieldset[disabled], [inert], [aria-disabled=true]");
  const name = (el) => [el.getAttribute("aria-label"), ...[...(el.labels || [])].map((l) => l.textContent)].join(" ");
  const sliders = [...document.querySelectorAll("input[type=range]")].filter((s) => vis(s) && !s.disabled &&
      (locked || /entsperr|freischalt|unlock|ziehen|schieben|slide|drag/i.test(name(s))) && String(s.value) !== String(s.max || 100));
  const boxes = [...document.querySelectorAll("input[type=checkbox]")].filter((c) => vis(c) && !c.disabled && !c.checked &&
      /roboter|robot|mensch|human/i.test(name(c)));
  sliders.forEach((s, i) => s.setAttribute("data-agent-guard", "slider" + i));
  boxes.forEach((c, i) => c.setAttribute("data-agent-guard", "human" + i));
  return {sliders: sliders.length, boxes: boxes.length};
}"""


async def unlock_gate(s: SiteSession) -> bool:
    """Move unlock sliders to the end and tick 'not a robot' boxes, in every frame. True if anything was done."""
    acted = False
    for frame in _frames(s.page):
        try:
            found = await frame.evaluate(GATE_JS)
        except Exception:
            continue
        for i in range(found["sliders"]):
            loc = frame.locator(f'[data-agent-guard="slider{i}"]')
            try:
                await loc.fill(await loc.evaluate("e => String(e.max || 100)"), timeout=3000)
                acted = True
            except Exception:
                pass
        for i in range(found["boxes"]):
            try:
                await frame.locator(f'[data-agent-guard="human{i}"]').check(timeout=3000)
                acted = True
            except Exception:
                pass
    if acted:
        await settle(s.page)
        s.note("Freigabe-Schieberegler/„kein Roboter“ automatisch gesetzt")
    return acted


